//! The graphics backends, checked against the C library's `grf_log.c`.
//!
//! `grf_log_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/grf_log_probe.c`, which drives `grf_log.c` through
//! a fixed sequence of calls covering every function and attribute of the
//! C graphics interface, and records what each call returned, the call log
//! and the SVG. Each backend replays the same sequence here.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "grf_log_oracle/cases.rs"]
mod cases;

use cases::{Call, Expected};
use starlink_ast::error::ErrorCode;
use starlink_ast::grf::{
    Grf, GrfAttr, GrfCap, GrfPrimitive, Justification, LogGrf, SvgGrf, SvgOptions,
};

fn attr(name: &str) -> GrfAttr {
    match name {
        "Style" => GrfAttr::Style,
        "Width" => GrfAttr::Width,
        "Size" => GrfAttr::Size,
        "Font" => GrfAttr::Font,
        "Colour" => GrfAttr::Colour,
        _ => panic!("unknown attribute {name}"),
    }
}

fn prim(name: &str) -> GrfPrimitive {
    match name {
        "Text" => GrfPrimitive::Text,
        "Line" => GrfPrimitive::Line,
        "Mark" => GrfPrimitive::Mark,
        _ => panic!("unknown primitive {name}"),
    }
}

fn cap(name: &str) -> GrfCap {
    match name {
        "Escapes" => GrfCap::Escapes,
        "MJust" => GrfCap::MJust,
        "Scales" => GrfCap::Scales,
        _ => panic!("unknown capability {name}"),
    }
}

fn bits(v: &[f32]) -> Vec<u32> {
    v.iter().map(|x| x.to_bits()).collect()
}

/// Replay the probe's calls through `grf`, checking each return.
fn replay(grf: &mut dyn Grf) {
    for (i, (call, want)) in cases::CALLS.iter().enumerate() {
        let what = format!("call {i}: {call:?}");
        match (call, want) {
            (Call::Scales, Expected::Pair(p)) => {
                assert_eq!(bits(&grf.scales().unwrap()), bits(p), "{what}");
            }
            (Call::Qch, Expected::Pair(p)) => {
                assert_eq!(bits(&grf.char_height().unwrap()), bits(p), "{what}");
            }
            (Call::TxExt(t, x, y, j, up), want) => {
                let got = grf.text_extent(t, *x, *y, Justification::from_code(j).unwrap(), *up);
                match want {
                    Expected::Box(bx, by) => {
                        let got = got.unwrap();
                        assert_eq!((bits(&got.x), bits(&got.y)), (bits(bx), bits(by)), "{what}");
                    }
                    Expected::Error => {
                        assert_eq!(got.unwrap_err().code(), ErrorCode::Grfer, "{what}");
                    }
                    _ => panic!("{what}: unexpected expectation {want:?}"),
                }
            }
            (Call::Text(t, x, y, j, up), Expected::Done) => {
                grf.text(t, *x, *y, Justification::from_code(j).unwrap(), *up)
                    .unwrap();
            }
            (Call::Line(x, y), Expected::Done) => grf.line(x, y).unwrap(),
            (Call::Mark(x, y, m), Expected::Done) => grf.mark(x, y, *m).unwrap(),
            (Call::Attr(a, v, p), Expected::Previous(old)) => {
                assert_eq!(grf.attr(attr(a), *v, prim(p)).unwrap(), *old, "{what}");
            }
            (Call::Cap(c, v), Expected::Cap(has)) => {
                assert_eq!(grf.cap(cap(c), *v), *has, "{what}");
            }
            (Call::BBuf, Expected::Done) => grf.begin_buffer().unwrap(),
            (Call::EBuf, Expected::Done) => grf.end_buffer().unwrap(),
            (Call::Flush, Expected::Done) => grf.flush().unwrap(),
            _ => panic!("{what}: unexpected expectation {want:?}"),
        }
    }
}

/// Assert two multi-line texts are equal, reporting the first differing
/// line.
fn assert_lines_eq(got: &str, want: &str, what: &str) {
    if got == want {
        return;
    }
    for (i, (g, w)) in got.lines().zip(want.lines()).enumerate() {
        assert_eq!(g, w, "{what}: first difference at line {}", i + 1);
    }
    assert_eq!(
        got.len(),
        want.len(),
        "{what}: one is a prefix of the other"
    );
    panic!("{what}: texts differ only in line endings");
}

#[test]
fn log_grf_matches_the_c_library() {
    let mut grf = LogGrf::new(Vec::new());
    replay(&mut grf);
    let log = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert_lines_eq(&log, cases::LOG, "log");
}

#[test]
fn svg_grf_matches_the_c_library() {
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    replay(&mut grf);
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert_lines_eq(&svg, cases::SVG, "svg");
}

/// The page size can be set field by field, which is how options added
/// later stay compatible.
#[test]
fn svg_options_set_the_page_size() {
    let mut options = SvgOptions::default();
    assert_eq!((options.width, options.height), (720, 540));
    options.width = 800;
    options.height = 600;
    let grf = SvgGrf::new(Vec::new(), options).unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(
        svg.contains("width=\"800\" height=\"600\" viewBox=\"0 0 800 600\""),
        "{svg}"
    );
    assert!(svg.ends_with("</svg>\n"), "{svg}");
}

#[test]
fn justification_round_trips_its_code() {
    for v in ["M", "B", "C", "T"] {
        for h in ["L", "C", "R"] {
            let code = format!("{v}{h}");
            let just = Justification::from_code(&code).unwrap();
            assert_eq!(just.code(), code.as_bytes(), "{code}");
        }
    }
    for bad in ["XX", "C", "CCC", "LC", ""] {
        assert_eq!(
            Justification::from_code(bad).unwrap_err().code(),
            ErrorCode::Grfer,
            "{bad:?}"
        );
    }
}

#[test]
fn mismatched_points_are_an_error() {
    let mut log = LogGrf::new(Vec::new());
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    for grf in [&mut log as &mut dyn Grf, &mut svg as &mut dyn Grf] {
        assert_eq!(
            grf.line(&[0.1, 0.2], &[0.1]).unwrap_err().code(),
            ErrorCode::Grfer
        );
        assert_eq!(
            grf.mark(&[0.1], &[], 1).unwrap_err().code(),
            ErrorCode::Grfer
        );
    }
}

/// The provided backends take `BAD_VALUE` as a query, as the C library
/// does: nothing is set and nothing is logged.
#[test]
fn provided_backends_take_a_bad_value_as_a_query() {
    use starlink_ast::constants::BAD_VALUE;
    let mut log = LogGrf::new(Vec::new());
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    for grf in [&mut log as &mut dyn Grf, &mut svg as &mut dyn Grf] {
        grf.attr(GrfAttr::Colour, Some(3.0), GrfPrimitive::Line)
            .unwrap();
        assert_eq!(
            grf.attr(GrfAttr::Colour, Some(BAD_VALUE), GrfPrimitive::Line)
                .unwrap(),
            3.0
        );
        assert_eq!(
            grf.attr(GrfAttr::Colour, None, GrfPrimitive::Line).unwrap(),
            3.0
        );
    }
    let log = String::from_utf8(log.finish().unwrap()).unwrap();
    assert_eq!(log, "GAttr COLOUR=3.0000 prim=LINE\n");
}

/// A backend need not write the buffering and flushing methods, whose
/// defaults do nothing.
#[test]
fn buffering_and_flushing_default_to_nothing() {
    use starlink_ast::error::AstResult;
    use starlink_ast::grf::TextBox;

    struct Minimal;
    impl Grf for Minimal {
        fn line(&mut self, _x: &[f32], _y: &[f32]) -> AstResult<()> {
            Ok(())
        }
        fn mark(&mut self, _x: &[f32], _y: &[f32], _marker: i32) -> AstResult<()> {
            Ok(())
        }
        fn text(
            &mut self,
            _t: &str,
            _x: f32,
            _y: f32,
            _j: Justification,
            _up: [f32; 2],
        ) -> AstResult<()> {
            Ok(())
        }
        fn text_extent(
            &mut self,
            _t: &str,
            _x: f32,
            _y: f32,
            _j: Justification,
            _up: [f32; 2],
        ) -> AstResult<TextBox> {
            Ok(TextBox {
                x: [0.0; 4],
                y: [0.0; 4],
            })
        }
        fn char_height(&mut self) -> AstResult<[f32; 2]> {
            Ok([0.01, 0.01])
        }
        fn scales(&mut self) -> AstResult<[f32; 2]> {
            Ok([1.0, 1.0])
        }
        fn attr(&mut self, _a: GrfAttr, _v: Option<f64>, _p: GrfPrimitive) -> AstResult<f64> {
            Ok(1.0)
        }
        fn cap(&mut self, _c: GrfCap, _v: i32) -> bool {
            false
        }
    }
    let mut grf = Minimal;
    grf.begin_buffer().unwrap();
    grf.end_buffer().unwrap();
    grf.flush().unwrap();
}
